class Solution {
public:
    int countGoodArrays(int n, int m, int k) {
        const int MOD = 1e9 + 7;
        if (k < 0 || k >= n) return 0;

        vector<long long> fact(n, 1), inv(n, 1);
        for (int i = 1; i < n; ++i) fact[i] = (fact[i - 1] * i) % MOD;

        auto power = [&](long long base, long long exp) {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp /= 2;
            }
            return res;
        };

        inv[n - 1] = power(fact[n - 1], MOD - 2);
        for (int i = n - 2; i >= 0; --i) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        auto nCr = [&](int nVal, int rVal) -> long long {
            if (rVal < 0 || rVal > nVal) return 0;
            return fact[nVal] * inv[rVal] % MOD * inv[nVal - rVal] % MOD;
        };

        long long comb = nCr(n - 1, k);
        long long ans = (comb * m) % MOD;
        long long remP = power(m - 1, n - 1 - k);
        return (ans * remP) % MOD;
    }
};

class Solution {
    private long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }

    public int countGoodArrays(int n, int m, int k) {
        long MOD = 1_000_000_007;
        if (k < 0 || k >= n) return 0;

        long[] fact = new long[n];
        long[] inv = new long[n];
        fact[0] = 1;
        for (int i = 1; i < n; ++i) fact[i] = (fact[i - 1] * i) % MOD;
        inv[n - 1] = power(fact[n - 1], MOD - 2, MOD);
        for (int i = n - 2; i >= 0; --i) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        long comb = fact[n - 1] * inv[k] % MOD * inv[n - 1 - k] % MOD;
        long ans = (comb * m) % MOD;
        long remP = power(m - 1, n - 1 - k, MOD);
        return (int)((ans * remP) % MOD);
    }
}

var countGoodArrays = function(n, m, k) {
    const MOD = 1000000007n;
    if (k < 0 || k >= n) return 0;

    const power = (base, exp) => {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    };

    const fact = new Array(n);
    const inv = new Array(n);
    fact[0] = 1n;
    for (let i = 1; i < n; ++i) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    inv[n - 1] = power(fact[n - 1], MOD - 2n);
    for (let i = n - 2; i >= 0; --i) inv[i] = (inv[i + 1] * BigInt(i + 1)) % MOD;

    const comb = fact[n - 1] * inv[k] % MOD * inv[n - 1 - k] % MOD;
    const ans = (comb * BigInt(m)) % MOD;
    const remP = power(m - 1, n - 1 - k);
    return Number((ans * remP) % MOD);
};
